version.transform:
(
  $fitModeToRange := function($startBound, $endBound, $mode){(

    $modeStart := $coalesce([ $mode.occurAt , $startBound])~>$moment(?) ;
    $modeEnd := $coalesce([ $mode.endAt, $endBound])~>$moment(?);

    $endBoundObj := $moment($endBound);
    $startBoundObj := $moment($startBound);

    $start := $modeStart.isAfter($startBound)? $modeStart : $startBoundObj;
    $end := $modeEnd.isBefore($endBound)? $modeEnd : $endBoundObj;

    $isNilOrEmpty($mode.occurAt) and $isNilOrEmpty($mode.endAt)? 
      $throw("Mode has no occurAt or endAt", $mode) :
      $merge([
        $mode,
        {"occurAt": $start.format(), "endAt": $end.format(), "originalTimes":{"occurAt": $modeStart, "endAt": $endAt}}
      ])

  )};
  $durationOrNow := function($v){(
    $end := $moment();
    $mode := $fitModeToRange($$.startAt, $end.format(), $v);

    $start := $moment($mode.occurAt);

    $durationTillNow := $end.diff($start, "seconds");

    $coalesce([$mode.duration, $durationTillNow])

  )};
  $date := $moment(startAt);

  $data := $leftOuterJoin( 
    [modeTypes], 
    [history], 
    'name', 
    $path(?, ["mode", "modeType", "name"]), 
    'history', 
    { 'grouped': true } 
  )
    ~>$map(
      | $ | { "value": $coalesce([ $sum( history.($durationOrNow($))), 0 ]) / 3600, "label": name }, ["history", "name"] |
    );

  {
    "chart":{
      "caption": "Shift Status",
      "subCaption": $date.format("MM/DD") & " - " & $$.shiftName,
      "yAxisName": "Time",
      "numberSuffix": "h"
    },
    "data": $data
  }
)
